<?php require '../config/database.php';auth();$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();$techs=$pdo->query("SELECT id,name FROM technicians WHERE status='active' ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO repairs(customer_id,technician_id,device_type,device_model,serial_number,problem,estimated_cost) VALUES(?,?,?,?,?,?,?)');$s->execute([(int)$_POST['customer_id'],$_POST['technician_id']?:null,$_POST['device_type'],$_POST['device_model'],$_POST['serial_number'],$_POST['problem'],(float)$_POST['estimated_cost']]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>فتح طلب صيانة</h1><form method="post"><label>العميل</label><select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label>الفني</label><select name="technician_id"><option value="">غير محدد</option><?php foreach($techs as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['name'])?></option><?php endforeach;?></select><label>نوع الجهاز</label><input name="device_type" required><label>الموديل</label><input name="device_model"><label>الرقم التسلسلي</label><input name="serial_number"><label>المشكلة</label><textarea name="problem" required></textarea><label>التكلفة المتوقعة</label><input type="number" step="0.01" name="estimated_cost" value="0"><button>حفظ</button></form></main>
